//! No-search single-combat PPO lane. Same corrected simulator and NUM1 action records.
use super::*;
use serde::{Serialize,Deserialize};
use std::hash::{Hash,Hasher};
struct Fight {session:Session,fixture:usize,episode:usize,generation:u64,actions:Vec<usize>}
struct Curriculum {schema:Arc<Schema>,threads:Arc<rayon::ThreadPool>,templates:Vec<Session>,cells:Vec<usize>,schedule:Vec<usize>,next:usize,slots:Vec<Fight>,admitted:[u64;8],completed:[u64;3]}
fn private(s:&Session)->Result<Vec<Row>>{let mut out=vec![[0;16]];if s.state.player.deferred_draw_order{return Err("curriculum requires real draw order, not search belief state".into())}
 for(i,uid)in s.state.player.draw.iter().enumerate(){let c=sts2_core::card_by_uid(&s.state.cards,*uid).ok_or("missing private draw card")?;row(&mut out,1,1+2*c.card_id as i32+i32::from(c.upgraded),-1,i as i32,&[c.cost.into(),c.base_damage,c.base_block]);}out[0][10]=out.len() as i32-1;Ok(out)}
fn encode(f:&mut Fight,schema:&Schema)->Result<Vec<Row>>{let mut out=Vec::new();f.session.numeric_direct(schema,&mut out,0)?;
 let at=out[0][11] as usize+1;let mut marker=[0;16];marker[..7].copy_from_slice(&[31,6,-1,0,1,f.session.initial_hp,(500-f.session.decisions.min(500)) as i32]);out.insert(at,marker);
 out[0][3]=out.len() as i32-1;out[0][10]=out.len() as i32-1;out[0][11]+=1;out[0][6]=f.generation as i32;out[0][7]=(f.generation>>32) as i32;out[0][8]=1;out[0][9]=2;
 Ok(out)}
fn reward(hp:i32,start:i32,win:bool,timeout:bool)->Result<f32>{if start<=0{return Err("nonpositive curriculum starting HP".into())}Ok(if win&&!timeout&&hp>0{(hp as f32/start as f32).clamp(0.,1.)+0.1}else{0.})}
impl Curriculum{
 fn fresh(&self,id:usize,generation:u64)->Result<Fight>{let fixture=*self.schedule.get(id%self.schedule.len()).ok_or("prepared combat schedule exhausted")?;Ok(Fight{session:self.templates[fixture].clone(),fixture,episode:id,generation,actions:Vec::new()})}
}
#[no_mangle]pub unsafe extern "C" fn sm_cc_create(schema:*const c_char,path:*const c_char,schedule:*const c_char,n:usize,workers:usize)->*mut c_void{let mut out=std::ptr::null_mut();guarded(||{
 if n==0||workers==0{return Err("invalid curriculum dimensions".into())}
 let root=CStr::from_ptr(schema).to_str().map_err(|e|e.to_string())?;let labels:Vec<Value>=serde_json::from_str(&std::fs::read_to_string(format!("{root}/registry.json")).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;let metadata=serde_json::from_str(&std::fs::read_to_string(format!("{root}/metadata.json")).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;let schema=Arc::new(Schema::new(&labels,metadata)?);
 let threads=Arc::new(rayon::ThreadPoolBuilder::new().num_threads(workers).build().map_err(|e|e.to_string())?);
 let path=CStr::from_ptr(path).to_str().map_err(|e|e.to_string())?;let fixtures:Vec<Value>=std::fs::read_to_string(path).map_err(|e|e.to_string())?.lines().map(|l|serde_json::from_str(l).map_err(|e|e.to_string())).collect::<Result<_>>()?;
 let cells:Vec<usize>=fixtures.iter().map(|f|f["curriculum_cell"].as_u64().ok_or("missing curriculum cell").and_then(|v|if v<8{Ok(v as usize)}else{Err("invalid curriculum cell")})).collect::<std::result::Result<_,_>>().map_err(str::to_owned)?;
 let templates:Result<Vec<_>>=threads.install(||fixtures.par_iter().enumerate().map(|(i,f)|{let state=sts2_wire::state_from_fixture_json(&f["wire"]).map_err(|e|format!("fixture {i}: {e}"))?;let mut s=Session::from_parts(&schema,state,f["context"].clone(),500)?;if s.initial_hp<=0||s.done(){return Err(format!("invalid starting combat {i}"))}let mut rows=Vec::new();s.numeric_direct(&schema,&mut rows,0)?;Ok(s)}).collect());
 let p=CStr::from_ptr(schedule).to_str().map_err(|e|e.to_string())?;let schedule:Vec<usize>=serde_json::from_str(&std::fs::read_to_string(p).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;if schedule.len()<n||schedule.iter().any(|&i|i>=fixtures.len()){return Err("invalid prepared combat schedule".into())}
 let mut pool=Curriculum{schema,threads,templates:templates?,cells,schedule,next:n,slots:Vec::new(),admitted:[0;8],completed:[0;3]};
 for i in 0..n{let f=pool.fresh(i,0)?;pool.admitted[pool.cells[f.fixture]]+=1;pool.slots.push(f);}out=Box::into_raw(Box::new(pool)) as *mut c_void;Ok(())});out}
#[no_mangle]pub unsafe extern "C" fn sm_cc_destroy(p:*mut c_void){if !p.is_null(){drop(Box::from_raw(p as *mut Curriculum));}}
#[no_mangle]pub unsafe extern "C" fn sm_cc_encode(p:*mut c_void,raw:*mut i32,capacity:usize,lengths:*mut u32,counts:*mut u32,privdata:*mut i32,privcap:usize,privlengths:*mut u32)->i32{guarded(||{let p=&mut*(p as *mut Curriculum);let schema=&p.schema;
 let all:Result<Vec<_>>=p.threads.install(||p.slots.par_iter_mut().map(|f|Ok((encode(f,schema)?,private(&f.session)?))).collect());let all=all?;
 let n=p.slots.len();let raw=std::slice::from_raw_parts_mut(raw,n*capacity*16);let pd=std::slice::from_raw_parts_mut(privdata,n*privcap*16);let lens=std::slice::from_raw_parts_mut(lengths,n);let pc=std::slice::from_raw_parts_mut(privlengths,n);let counts=std::slice::from_raw_parts_mut(counts,n);
 for(i,(rows,pr))in all.iter().enumerate(){if rows.len()>capacity||pr.len()>privcap{return Err(format!("curriculum observation capacity exceeded in slot {i}: {} / {}",rows.len(),pr.len()))}for(j,r)in rows.iter().enumerate(){raw[i*capacity*16+j*16..i*capacity*16+(j+1)*16].copy_from_slice(r);}for(j,r)in pr.iter().enumerate(){pd[i*privcap*16+j*16..i*privcap*16+(j+1)*16].copy_from_slice(r);}lens[i]=rows.len() as u32;pc[i]=pr.len() as u32;counts[i]=p.slots[i].session.commands.len() as u32;}Ok(())})}
#[no_mangle]pub unsafe extern "C" fn sm_cc_step(p:*mut c_void,actions:*const i32,generations:*const u64,events:*mut i32,rewards:*mut f32)->i32{guarded(||{let p=&mut*(p as *mut Curriculum);let n=p.slots.len();let a=std::slice::from_raw_parts(actions,n);let g=std::slice::from_raw_parts(generations,n);
 for(i,f)in p.slots.iter().enumerate(){if a[i]<0||g[i]!=f.generation||a[i] as usize>=f.session.commands.len()||f.session.done(){return Err(format!("invalid/stale curriculum action in slot {i}"))}}
 let ev=std::slice::from_raw_parts_mut(events,n*8);let rw=std::slice::from_raw_parts_mut(rewards,n);
 p.threads.install(||p.slots.par_iter_mut().zip(a).zip(ev.par_chunks_mut(8)).zip(rw).try_for_each(|(((f,&a),ev),rw)|{f.session.step(a as usize)?;f.actions.push(a as usize);f.generation+=1;let done=f.session.done();let win=f.session.state.is_over&&f.session.state.player_won;let timeout=!f.session.state.is_over&&done;ev.fill(0);ev[4]=i32::from(done);ev[5]=i32::from(win);ev[6]=f.session.state.player.current_hp;ev[7]=i32::from(timeout);*rw=if done{reward(f.session.state.player.current_hp,f.session.initial_hp,win,timeout)?}else{0.};Ok(())}))
})}
#[no_mangle]pub unsafe extern "C" fn sm_cc_reset(p:*mut c_void)->i32{let mut count=0;let code=guarded(||{let p=&mut*(p as *mut Curriculum);let ids:Vec<_>=p.slots.iter().enumerate().filter(|(_,f)|f.session.done()).map(|(i,_)|i).collect();
 for i in ids{let f=&p.slots[i];let result=if f.session.state.is_over{usize::from(!f.session.state.player_won)}else{2};p.completed[result]+=1;let next=p.fresh(p.next,f.generation+1)?;p.admitted[p.cells[next.fixture]]+=1;p.slots[i]=next;p.next+=1;count+=1;}Ok(())});if code<0{code}else{count}}
#[derive(Serialize,Deserialize)]struct Journal{version:u32,next:usize,admitted:[u64;8],completed:[u64;3],slots:Vec<JS>}
#[derive(Serialize,Deserialize)]struct JS{fixture:usize,episode:usize,generation:u64,actions:Vec<usize>,state:u64,frame:u64}
fn frame_hash(rows:&[Row])->u64{let mut h=std::collections::hash_map::DefaultHasher::new();rows.hash(&mut h);h.finish()}
#[no_mangle]pub unsafe extern "C" fn sm_cc_journal(p:*mut c_void)->*const c_char{let mut out=std::ptr::null();guarded(||{let p=&mut*(p as *mut Curriculum);let mut slots=Vec::new();for f in &mut p.slots{let rows=encode(f,&p.schema)?;slots.push(JS{fixture:f.fixture,episode:f.episode,generation:f.generation,actions:f.actions.clone(),state:sts2_core::hashing::state_hash(&f.session.state),frame:frame_hash(&rows)})}let j=Journal{version:1,next:p.next,admitted:p.admitted,completed:p.completed,slots};OUTPUT.with(|v|{*v.borrow_mut()=CString::new(serde_json::to_string(&j).unwrap()).unwrap();out=v.borrow().as_ptr()});Ok(())});out}
#[no_mangle]pub unsafe extern "C" fn sm_cc_restore(p:*mut c_void,text:*const c_char)->i32{guarded(||{let p=&mut*(p as *mut Curriculum);let j:Journal=serde_json::from_str(CStr::from_ptr(text).to_str().map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;if j.version!=1||j.slots.len()!=p.slots.len(){return Err("curriculum journal dimensions".into())}
 let mut restored=Vec::new();for s in j.slots{if p.schedule.get(s.episode%p.schedule.len())!=Some(&s.fixture){return Err("curriculum schedule provenance mismatch".into())}let mut f=p.fresh(s.episode,s.generation)?;for a in &s.actions{let _=encode(&mut f,&p.schema)?;f.session.step(*a)?;f.actions.push(*a);}let rows=encode(&mut f,&p.schema)?;if sts2_core::hashing::state_hash(&f.session.state)!=s.state||frame_hash(&rows)!=s.frame{return Err("curriculum state/RNG/encoding replay mismatch".into())}restored.push(f);}p.slots=restored;p.next=j.next;p.admitted=j.admitted;p.completed=j.completed;Ok(())})}
#[no_mangle]pub unsafe extern "C" fn sm_cc_stats(p:*mut c_void)->*const c_char{let mut out=std::ptr::null();guarded(||{let p=&mut*(p as *mut Curriculum);OUTPUT.with(|v|{*v.borrow_mut()=CString::new(serde_json::json!({"next":p.next,"templates":p.templates.len(),"prepared_episodes":p.schedule.len(),"schedule_mode":"repeat_prepared_schedule","schedule_cycles":p.next/p.schedule.len(),"admitted_by_cell":p.admitted,"completed_win_loss_timeout":p.completed}).to_string()).unwrap();out=v.borrow().as_ptr()});Ok(())});out}
#[no_mangle]pub unsafe extern "C" fn sm_cc_test_reward(hp:i32,start:i32,win:bool,timeout:bool)->f32{reward(hp,start,win,timeout).unwrap_or(f32::NAN)}
#[no_mangle]pub unsafe extern "C" fn sm_cc_test_intervene(p:*mut c_void,i:usize)->i32{guarded(||{let p=&mut*(p as *mut Curriculum);p.slots.get_mut(i).ok_or("intervention slot")?.session.state.player.draw.reverse();Ok(())})}

#[no_mangle]pub unsafe extern "C" fn sm_cc_test_cap(p:*mut c_void,i:usize,limit:usize)->i32{guarded(||{let p=&mut*(p as *mut Curriculum);p.slots.get_mut(i).ok_or("test cap slot")?.session.max_actions=limit;Ok(())})}
